/** Notification URLs are generated by the database, but never trust a stored redirect. */
const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
export function notificationHref(value: string): string {
  if (new RegExp(`^/(?:mesajlar|ilanlar)/${UUID}$`, 'i').test(value)) return value;
  // İş ağı teklif bildirimleri mobilde /ag/ilan/<id>, webde /is-agi/ilan/<id>
  const ag = new RegExp(`^/ag/ilan/(${UUID})$`, 'i').exec(value);
  if (ag) return `/is-agi/ilan/${ag[1]}`;
  if (value === '/destek') return '/destek';
  // Kayıtlı aramalar webde bildirimler sayfasında listelenir
  if (value === '/kayitli-aramalar') return '/bildirimler';
  return '/bildirimler';
}
